package com.sistemahospitalar.hospital.controller; import com.sistemahospitalar.hospital.model.*; import com.sistemahospitalar.hospital.service.ProfissionalSaudeService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/profissionais") public class ProfissionalSaudeController {private final ProfissionalSaudeService service; public ProfissionalSaudeController(ProfissionalSaudeService s){service=s;} @GetMapping public List<ProfissionalSaude> listar(){return service.listar();} @GetMapping("/especialistas") public List<MedicoEspecialista> porEspecialidade(@RequestParam String especialidade){return service.porEspecialidade(especialidade);} @PostMapping public ResponseEntity<ProfissionalSaude> criar(@Valid @RequestBody ProfissionalSaude p){return ResponseEntity.status(HttpStatus.CREATED).body(service.salvar(p));} }
